<?php
namespace App\AI; use App\AI\Providers\OpenAICompatibleProvider; use App\Services\Database;
final class AIManager { public function run(string $promptKey,array $vars,array $options=[]): array { $pdo=Database::pdo(); $prompt=$pdo->prepare('SELECT * FROM ai_prompts WHERE prompt_key=? AND is_active=1'); $prompt->execute([$promptKey]); $tpl=$prompt->fetch() ?: ['system_prompt'=>'You are a careful resume assistant. Never invent facts; mark assumptions for review. Return JSON.','user_prompt'=>'Task: {{task}}']; $messages=[['role'=>'system','content'=>$this->replace($tpl['system_prompt'],$vars)],['role'=>'user','content'=>$this->replace($tpl['user_prompt'],$vars)]]; $providers=$pdo->query('SELECT * FROM ai_providers WHERE is_active=1 ORDER BY priority ASC,id ASC')->fetchAll(); $last=null; foreach($providers as $p){ $start=microtime(true); try { $res=(new OpenAICompatibleProvider($p))->generate($messages,$options+['temperature'=>$tpl['temperature'],'max_tokens'=>$tpl['max_tokens']]); $this->log($p,$promptKey,'success',$res['usage']??[],null,microtime(true)-$start); return $res; } catch(\Throwable $e){ $last=$e; $this->log($p,$promptKey,'failed',[],$e->getMessage(),microtime(true)-$start); }} throw new \RuntimeException('All AI providers failed: '.($last?->getMessage() ?? 'none configured')); } private function replace(string $s,array $vars): string { return preg_replace_callback('/{{\s*([a-zA-Z0-9_]+)\s*}}/',fn($m)=> (string)($vars[$m[1]] ?? ''),$s); } private function log(array $p,string $type,string $status,array $usage,?string $err,float $sec): void { try{ $db=Database::pdo(); $st=$db->prepare('INSERT INTO ai_logs(provider_id,model,request_type,status,tokens_input,tokens_output,error,response_time_ms,created_at) VALUES(?,?,?,?,?,?,?,?,NOW())'); $st->execute([$p['id']??null,$p['model']??null,$type,$status,$usage['prompt_tokens']??0,$usage['completion_tokens']??0,$err,(int)($sec*1000)]);}catch(\Throwable){}} }
